class _Api:
    """Immutable connection context for Management API calls.

    Attributes:
        mgmt_base: Full Management API base URL (instance URL + ``/management/v1``).
        token: Bearer token (the FIRSTINSTANCE machine-user PAT).
        host_header: Value sent as the HTTP ``Host`` header so the internally
            addressed request matches the Zitadel v3 instance.
    """

    __slots__ = ("mgmt_base", "token", "host_header")

    def __init__(self, mgmt_base: str, token: str, host_header: str) -> None:
        self.mgmt_base = mgmt_base
        self.token = token
        self.host_header = host_header


