def _require_env(name: str) -> str:
    """Return env var *name*, exiting non-zero when absent or empty."""
    value = os.environ.get(name, "").strip()
    if not value:
        logger.error(
            "Missing required environment variable '%s'. "
            "Fix: ensure the init-job container sets this variable before the "
            "applier runs.",
            name,
        )
        sys.exit(1)
    return value


def _read_pat(pat_file: str) -> str:
    """Read the FIRSTINSTANCE machine-user PAT from the shared volume file.

    Args:
        pat_file: Filesystem path to the PAT file the Zitadel server wrote during
            FIRSTINSTANCE setup (``ZITADEL_FIRSTINSTANCE_PATPATH``).

    Returns:
        The Personal Access Token string.

    Raises:
        SystemExit(1): When the file is missing or empty.
    """
    if not os.path.exists(pat_file):
        logger.error(
            "PAT file not found at '%s'. "
            "Fix: verify the Zitadel server's ZITADEL_FIRSTINSTANCE_PATPATH writes "
            "to this path and the init-job mounts the shared machinekey volume. "
            "Note: FIRSTINSTANCE only runs on a fresh instance — an existing "
            "deployment needs a zitadel-db-data volume reset to regenerate the PAT.",
            pat_file,
        )
        sys.exit(1)
    with open(pat_file, "r", encoding="utf-8") as fh:
        token = fh.read().strip()
    if not token:
        logger.error(
            "PAT file '%s' is empty. "
            "Fix: verify FIRSTINSTANCE setup completed and wrote the machine-user "
            "PAT before the server became healthy.",
            pat_file,
        )
        sys.exit(1)
    logger.info("pat_loaded path=%s", pat_file)
    return token


# ---------------------------------------------------------------------------
# HTTP helpers (stdlib only — no external dependencies)
