def _json_request(
    url: str,
    api: _Api,
    *,
    method: str = "GET",
    payload: dict[str, Any] | None = None,
) -> tuple[int, dict[str, Any]]:
    """Execute a JSON Management API request and return ``(status_code, body)``.

    Attaches the Bearer PAT and the instance ``Host`` header (so Zitadel v3 routes
    the request to the matching instance even though the URL targets the internal
    service name).

    Args:
        url: Full request URL.
        api: Connection context (base URL, token, host header).
        method: HTTP method (GET, POST, PUT, PATCH, etc.).
        payload: Dict to serialize as JSON request body. ``None`` for no body.

    Returns:
        ``(status_code, parsed_json_body)``.  When the response body is not valid
        JSON, returns an empty dict as the body.

    Raises:
        SystemExit(1): On network-level errors, logged with details.
    """
    data: bytes | None = None
    headers: dict[str, str] = {
        "Accept": "application/json",
        "Authorization": "Bearer %s" % api.token,
    }
    if payload is not None:
        headers["Content-Type"] = "application/json"
        data = json.dumps(payload).encode("utf-8")

    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    # Override the Host header (urllib would otherwise derive it from the URL's
    # internal service name, which does not match any Zitadel v3 instance).
    req.add_unredirected_header("Host", api.host_header)
    try:
        with urllib.request.urlopen(req) as resp:
            raw = resp.read()
            status = resp.status
    except urllib.error.HTTPError as exc:
        raw = exc.read()
        status = exc.code
    except urllib.error.URLError as exc:
        logger.error(
            "Network error calling '%s %s': %s. "
            "Fix: verify ZITADEL_INSTANCE_URL is reachable from the init container "
            "and that the server healthcheck passed before this job started.",
            method,
            url,
            exc.reason,
        )
        sys.exit(1)

    try:
        body: dict[str, Any] = json.loads(raw.decode("utf-8")) if raw else {}
    except json.JSONDecodeError:
        body = {}

    return status, body


def _is_no_changes(status: int, body: dict[str, Any]) -> bool:
    """Return ``True`` for Zitadel's HTTP 400 "No changes" no-op-update response.

    An idempotent re-run reissues update PUTs whose payload equals what Zitadel
    already stores. Zitadel rejects such no-op updates with
    ``HTTP 400 {"code":9,"message":"No changes (COMMAND-...)"}``. For a converged
    deployment that is the expected steady state, not a failure, so update callers
    treat it as success (the desired state is already applied).

    The match is case-insensitive: Zitadel is inconsistent about the casing of
    this message across endpoints — the flow-trigger SET returns
    ``"No Changes (COMMAND-Nfh52)"`` (capital C) while update PUTs return
    ``"No changes (...)"``. A case-sensitive check would miss the trigger-SET
    no-op and abort an otherwise-converged re-deploy.

    Args:
        status: HTTP status code from the update call.
        body: Parsed JSON response body.

    Returns:
        ``True`` when the response is a Zitadel "No changes" rejection.
    """
    if status != 400:
        return False
    message = body.get("message")
    return isinstance(message, str) and "no changes" in message.lower()


