def _load_artifact(path: str) -> dict[str, Any]:
    """Load and validate the provisioning artifact from *path*.

    Args:
        path: Filesystem path to ``zitadel-provisioning.json``.

    Returns:
        Parsed artifact dict with a ``"projects"`` key.

    Raises:
        SystemExit(1): When the file is missing, unreadable, not valid JSON,
            or does not contain the expected ``"projects"`` list.
    """
    if not os.path.exists(path):
        logger.error(
            "Provisioning artifact not found at '%s'. "
            "Fix: verify the artifact mount in the init-job volumes block and "
            "that datrix generated the file at 'config/identity/zitadel-provisioning.json'.",
            path,
        )
        sys.exit(1)

    try:
        with open(path, "r", encoding="utf-8") as fh:
            data: dict[str, Any] = json.load(fh)
    except json.JSONDecodeError as exc:
        logger.error(
            "Provisioning artifact at '%s' is not valid JSON: %s. "
            "Fix: regenerate the artifact with datrix.",
            path,
            exc,
        )
        sys.exit(1)

    if not isinstance(data.get("projects"), list):
        logger.error(
            "Provisioning artifact at '%s' must have a 'projects' list at the top level. "
            "Got keys: %s. "
            "Fix: regenerate the artifact — the schema is managed by datrix-codegen-docker.",
            path,
            sorted(data.keys()) if isinstance(data, dict) else type(data).__name__,
        )
        sys.exit(1)

    return data


