def _list_projects(api: _Api) -> list[dict[str, Any]]:
    """Fetch all existing Zitadel projects.

    Zitadel exposes project listing only via the search endpoint
    (``POST /management/v1/projects/_search``); a plain ``GET /projects`` returns
    HTTP 405 (Method Not Allowed). This mirrors every other list call in this
    file (roles/apps/idps all use ``_search``).
    """
    url = api.mgmt_base + "/projects/_search"
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list projects (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has IAM_OWNER permissions.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result  # type: ignore[return-value]
    return []


def _find_project_by_name(
    projects: list[dict[str, Any]], name: str
) -> dict[str, Any] | None:
    """Return the first project entry whose ``name`` matches, or ``None``."""
    for p in projects:
        if p.get("name") == name:
            return p
    return None


def _create_project(api: _Api, name: str, role_assertion: bool) -> str:
    """Create a Zitadel project with *name* and return its project ID.

    Args:
        api: Connection context.
        name: Project name.
        role_assertion: Value for ``projectRoleAssertion`` ("Assert Roles on
            Authentication").  Zitadel only mints the
            ``urn:zitadel:iam:org:project:roles`` claim into tokens when this is
            true, so a project with roles must enable it or every role-guarded
            route 403s.  Defaults to ``false`` on create when omitted, so it is
            sent explicitly.

    Returns:
        The new project's ``id`` string.

    Raises:
        SystemExit(1): On API error.
    """
    url = api.mgmt_base + "/projects"
    payload: dict[str, Any] = {"name": name, "projectRoleAssertion": role_assertion}
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create project '%s' (HTTP %d): %s.",
            name,
            status,
            body,
        )
        sys.exit(1)
    project_id = body.get("id")
    if not isinstance(project_id, str) or not project_id:
        logger.error(
            "Create project '%s' response missing 'id'. Got: %s.",
            name,
            body,
        )
        sys.exit(1)
    logger.info("project_created name=%s id=%s", name, project_id)
    return project_id


def _update_project(
    api: _Api, project_id: str, name: str, role_assertion: bool
) -> None:
    """Update the project name and role assertion (PUT /projects/{id}).

    A full-replace project PUT that omits ``projectRoleAssertion`` resets it to
    ``false``, which drops the project-roles claim and 403s every role-guarded
    route — so it is re-asserted on every update.  An existing project created
    before this flag was emitted (or by an older applier) is converged here.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        name: New project name.
        role_assertion: Value for ``projectRoleAssertion`` ("Assert Roles on
            Authentication").

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/projects/%s" % (api.mgmt_base, project_id)
    payload: dict[str, Any] = {"name": name, "projectRoleAssertion": role_assertion}
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update project id=%s name=%s (HTTP %d): %s.",
            project_id,
            name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("project_updated id=%s name=%s", project_id, name)


def _ensure_project(api: _Api, name: str, role_assertion: bool) -> str:
    """Idempotently get-or-create a Zitadel project and converge its role assertion.

    Fetches the project list first; creates the project when absent.  When the
    project already exists it is PUT-updated so ``projectRoleAssertion`` converges
    to the desired value (the create-time flag never reaches a project that was
    created before this fix), mirroring how roles and OIDC apps are reconciled.
    Zitadel's "No changes" 400 on a converged re-run is treated as success.

    Args:
        api: Connection context.
        name: Desired project name.
        role_assertion: Desired ``projectRoleAssertion`` value for the project.

    Returns:
        The project ID (existing or newly created).
    """
    existing = _list_projects(api)
    match = _find_project_by_name(existing, name)
    if match is not None:
        project_id = match.get("id")
        if not isinstance(project_id, str) or not project_id:
            logger.error(
                "Existing project '%s' has no id. Got: %s.",
                name,
                match,
            )
            sys.exit(1)
        logger.info("project_exists name=%s id=%s", name, project_id)
        _update_project(api, project_id, name, role_assertion)
        return project_id
    return _create_project(api, name, role_assertion)


