def _list_apps(api: _Api, project_id: str) -> list[dict[str, Any]]:
    """Fetch all existing apps for *project_id*."""
    url = "%s/projects/%s/apps/_search" % (api.mgmt_base, project_id)
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list apps for project id=%s (HTTP %d): %s.",
            project_id,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result  # type: ignore[return-value]
    return []


#: OIDC-config fields that a full-replace ``oidc_config`` PUT resets to their
#: defaults when omitted: ``devMode`` (omitting it resets to ``false``, which
#: makes Zitadel reject ``http://localhost`` redirect URIs), ``accessTokenType``
#: (resets to opaque, which the JWKS-validating backend cannot verify),
#: ``loginVersion`` (the per-app custom-login base URI), and the role-assertion
#: flags ``accessTokenRoleAssertion`` / ``idTokenRoleAssertion`` (each resets to
#: ``false``, which drops the project-roles claim and 403s every role-guarded
#: route).  Both create and update payloads must carry these so a redeploy never
#: strips them.
_OIDC_PRESERVED_FIELDS: tuple[str, ...] = (
    "devMode",
    "accessTokenType",
    "loginVersion",
    "accessTokenRoleAssertion",
    "idTokenRoleAssertion",
)


def _oidc_preserved_fields(app: dict[str, Any]) -> dict[str, Any]:
    """Return the subset of *app* fields that must survive a full-replace PUT.

    Only keys actually present in the artifact are returned, so the applier
    never sends a field the generator did not emit.
    """
    return {key: app[key] for key in _OIDC_PRESERVED_FIELDS if key in app}


def _create_oidc_app(
    api: _Api,
    project_id: str,
    app: dict[str, Any],
) -> str:
    """Create an OIDC application under *project_id* and return its ``appId``.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        app: OIDC app dict from the artifact.

    Returns:
        The new app's ``appId`` string.

    Raises:
        SystemExit(1): On missing fields or API error.
    """
    name = app.get("name")
    redirect_uris = app.get("redirectUris", [])
    response_types = app.get("responseTypes", [])
    grant_types = app.get("grantTypes", [])
    app_type = app.get("appType")
    auth_method = app.get("authMethodType")

    if not isinstance(name, str) or not name:
        logger.error(
            "OIDC app entry missing required 'name' field. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            app,
        )
        sys.exit(1)

    payload: dict[str, Any] = {
        "name": name,
        "redirectUris": redirect_uris,
        "responseTypes": response_types,
        "grantTypes": grant_types,
        "appType": app_type,
        "authMethodType": auth_method,
    }
    payload.update(_oidc_preserved_fields(app))
    url = "%s/projects/%s/apps/oidc" % (api.mgmt_base, project_id)
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create OIDC app '%s' in project=%s (HTTP %d): %s.",
            name,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    app_id = body.get("appId")
    if not isinstance(app_id, str) or not app_id:
        logger.error(
            "Create OIDC app '%s' response missing 'appId'. Got: %s.",
            name,
            body,
        )
        sys.exit(1)
    logger.info("oidc_app_created project=%s name=%s appId=%s", project_id, name, app_id)
    return app_id


def _update_oidc_app(
    api: _Api,
    project_id: str,
    app_id: str,
    app: dict[str, Any],
) -> None:
    """Update OIDC config on an existing app.

    Zitadel's OIDC-app *create* endpoint is ``POST .../apps/oidc``, but the
    *update* endpoint is ``PUT .../apps/{appId}/oidc_config`` (different suffix).
    Using ``/oidc`` for the update returns HTTP 404.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/projects/%s/apps/%s/oidc_config" % (api.mgmt_base, project_id, app_id)
    payload: dict[str, Any] = {
        "redirectUris": app.get("redirectUris", []),
        "responseTypes": app.get("responseTypes", []),
        "grantTypes": app.get("grantTypes", []),
        "appType": app.get("appType"),
        "authMethodType": app.get("authMethodType"),
    }
    payload.update(_oidc_preserved_fields(app))
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update OIDC app id=%s in project=%s (HTTP %d): %s.",
            app_id,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info("oidc_app_updated project=%s appId=%s", project_id, app_id)


def _ensure_oidc_apps(
    api: _Api,
    project_id: str,
    oidc_apps: list[dict[str, Any]],
) -> None:
    """Idempotently create or update OIDC apps for a project.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        oidc_apps: List of OIDC app dicts from the artifact.
    """
    existing = _list_apps(api, project_id)
    existing_by_name: dict[str, dict[str, Any]] = {
        a.get("name", ""): a for a in existing
    }

    for app in oidc_apps:
        name = app.get("name")
        if not isinstance(name, str) or not name:
            logger.error(
                "OIDC app entry missing 'name'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                app,
            )
            sys.exit(1)
        if name in existing_by_name:
            existing_app = existing_by_name[name]
            app_id = existing_app.get("id")
            if not isinstance(app_id, str) or not app_id:
                logger.error(
                    "Existing app '%s' has no id. Got: %s.",
                    name,
                    existing_app,
                )
                sys.exit(1)
            _update_oidc_app(api, project_id, app_id, app)
        else:
            _create_oidc_app(api, project_id, app)


# ---------------------------------------------------------------------------
# Machine (service-account) provisioning
# ---------------------------------------------------------------------------

#: Access-token type for the inter-service machine user. JWT (not the default
#: opaque Bearer) is required so the callee can validate the inter-service token
#: via JWKS — an opaque token cannot be JWKS-validated.
_MACHINE_ACCESS_TOKEN_TYPE: str = "ACCESS_TOKEN_TYPE_JWT"

#: UID/GID of the non-root ``appuser`` that every generated backend service
#: container runs as (the Python service Dockerfile creates it with
#: ``--uid 1000 --gid 1000`` and runs ``USER appuser``).  This applier runs as
#: **root** in the Zitadel init container, so the shared machine-credentials file
#: it writes is chowned to this uid/gid — otherwise the ``0600`` file written by
#: root is unreadable by the non-root service users that must read it, and every
#: ``auth(service)`` call fails with PermissionError.  MUST stay in sync with the
#: appuser uid in the generated Python service Dockerfile.
_SERVICE_USER_UID: int = 1000


def _find_machine_user(api: _Api, user_name: str) -> str | None:
    """Return the existing machine user's id for *user_name*, or ``None``."""
    url = api.mgmt_base + "/users/_search"
    payload: dict[str, Any] = {
        "queries": [
            {
                "userNameQuery": {
                    "userName": user_name,
                    "method": "TEXT_QUERY_METHOD_EQUALS",
                }
            }
        ]
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 404):
        logger.error(
            "Failed to search users for '%s' (HTTP %d): %s.",
            user_name,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        for user in result:
            user_id = user.get("id") if isinstance(user, dict) else None
            if isinstance(user_id, str) and user_id:
                return user_id
    return None


def _create_machine_user(api: _Api, user_name: str, name: str) -> str:
    """Create a JWT-token machine (service-account) user and return its id.

    Raises:
        SystemExit(1): On API error or missing ``userId`` in the response.
    """
    url = api.mgmt_base + "/users/machine"
    payload: dict[str, Any] = {
        "userName": user_name,
        "name": name,
        "accessTokenType": _MACHINE_ACCESS_TOKEN_TYPE,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create machine user '%s' (HTTP %d): %s.",
            user_name,
            status,
            body,
        )
        sys.exit(1)
    user_id = body.get("userId")
    if not isinstance(user_id, str) or not user_id:
        logger.error(
            "Create machine user '%s' response missing 'userId'. Got: %s.",
            user_name,
            body,
        )
        sys.exit(1)
    logger.info("machine_user_created userName=%s id=%s", user_name, user_id)
    return user_id


def _ensure_machine_user(api: _Api, user_name: str, name: str) -> str:
    """Idempotently get-or-create the inter-service machine user."""
    existing = _find_machine_user(api, user_name)
    if existing is not None:
        logger.info("machine_user_exists userName=%s id=%s", user_name, existing)
        return existing
    return _create_machine_user(api, user_name, name)


def _find_org_member_roles(api: _Api, user_id: str) -> list[str] | None:
    """Return the existing org member's granted roles, or ``None`` if not a member.

    Uses ``POST /orgs/me/members/_search`` (ListOrgMembers) -- the org-member
    endpoints have no filter-by-single-user GET, matching every other list call
    in this applier (projects/roles/apps/actions all use ``_search``).

    Raises:
        SystemExit(1): On a non-200/404 API error.
    """
    url = api.mgmt_base + "/orgs/me/members/_search"
    payload: dict[str, Any] = {"queries": [{"userIdQuery": {"userId": user_id}}]}
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 404):
        logger.error(
            "Failed to list org members for user_id=%s (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has org-level permissions.",
            user_id,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        for member in result:
            if isinstance(member, dict) and member.get("userId") == user_id:
                roles = member.get("roles")
                if isinstance(roles, list):
                    return [r for r in roles if isinstance(r, str)]
                return []
    return None


def _ensure_org_user_manager_grant(api: _Api, user_id: str) -> None:
    """Idempotently grant the machine service account org-level metadata-write access.

    The generated runtime's Management-API metadata writer (a separate task)
    authenticates as this SAME machine service account via its
    own client_credentials token -- a different authorization path from the
    inter-service JWKS guard.  Without ``ORG_USER_MANAGER``,
    every metadata write is rejected and the syncOnAuth claim never appears --
    a silent tenancy outage (Risk 2).  Call only when the artifact's
    ``machineUser.grantsMetadataWrite`` is true.

    Raises:
        SystemExit(1): On any non-recoverable Management API error.
    """
    existing_roles = _find_org_member_roles(api, user_id)
    if existing_roles is None:
        url = api.mgmt_base + "/orgs/me/members"
        payload: dict[str, Any] = {
            "userId": user_id,
            "roles": [_ORG_USER_MANAGER_ROLE],
        }
        status, body = _json_request(url, api, method="POST", payload=payload)
        if status not in (200, 201) and not _is_no_changes(status, body):
            logger.error(
                "Failed to add org member grant for user_id=%s (HTTP %d): %s.",
                user_id,
                status,
                body,
            )
            sys.exit(1)
        logger.info("org_user_manager_grant_added user_id=%s", user_id)
        return
    if _ORG_USER_MANAGER_ROLE in existing_roles:
        logger.info("org_user_manager_grant_exists user_id=%s", user_id)
        return
    url = "%s/orgs/me/members/%s" % (api.mgmt_base, user_id)
    payload = {"roles": existing_roles + [_ORG_USER_MANAGER_ROLE]}
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update org member grant for user_id=%s (HTTP %d): %s.",
            user_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info(
        "org_user_manager_grant_updated user_id=%s roles=%s", user_id, payload["roles"]
    )


def _generate_machine_secret(api: _Api, user_id: str) -> tuple[str, str]:
    """Generate the machine user's client secret; return ``(clientId, clientSecret)``.

    Zitadel issues the secret once per call and rotates it on each call, so the
    applier rewrites the credentials file on every run; backend services depend on
    the init-job completing, so they always read the current secret.

    Raises:
        SystemExit(1): On API error or missing fields in the response.
    """
    url = "%s/users/%s/secret" % (api.mgmt_base, user_id)
    status, body = _json_request(url, api, method="PUT", payload={})
    if status not in (200, 201):
        logger.error(
            "Failed to generate machine secret for user id=%s (HTTP %d): %s.",
            user_id,
            status,
            body,
        )
        sys.exit(1)
    client_id = body.get("clientId")
    client_secret = body.get("clientSecret")
    if (
        not isinstance(client_id, str)
        or not client_id
        or not isinstance(client_secret, str)
        or not client_secret
    ):
        logger.error(
            "Generate machine secret for user id=%s response missing "
            "clientId/clientSecret. Got keys: %s.",
            user_id,
            sorted(body.keys()),
        )
        sys.exit(1)
    logger.info("machine_secret_generated user_id=%s clientId=%s", user_id, client_id)
    return client_id, client_secret


def _provision_machine_user(
    api: _Api,
    project: dict[str, Any],
    project_id: str,
) -> dict[str, str] | None:
    """Provision the machine user for a project and return its credential material.

    Returns ``None`` when the project declares no ``machineUser`` (non-machine
    audiences).  The returned dict carries three keys — ``clientId``,
    ``clientSecret``, and the reserved project-audience ``audience`` scope the
    caller requests so the issued token's ``aud`` matches the callee's
    ``allowedAudiences``.  The deployment-static ``tokenUrl`` and ``hostHeader``
    are added by ``main()`` before the credentials are persisted, so this
    function does not need them in scope.

    Raises:
        SystemExit(1): When ``machineUser`` is present but malformed.
    """
    machine_user = project.get("machineUser")
    if machine_user is None:
        return None
    if not isinstance(machine_user, dict):
        logger.error(
            "Project '%s' has a non-object 'machineUser'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            project.get("name"),
            machine_user,
        )
        sys.exit(1)
    user_name = machine_user.get("userName")
    if not isinstance(user_name, str) or not user_name:
        logger.error(
            "Project '%s' machineUser is missing 'userName'. Got: %s.",
            project.get("name"),
            machine_user,
        )
        sys.exit(1)
    display_name = machine_user.get("name")
    if not isinstance(display_name, str) or not display_name:
        display_name = user_name
    user_id = _ensure_machine_user(api, user_name, display_name)
    if bool(machine_user.get("grantsMetadataWrite", False)):
        _ensure_org_user_manager_grant(api, user_id)
    client_id, client_secret = _generate_machine_secret(api, user_id)
    return {
        "clientId": client_id,
        "clientSecret": client_secret,
        "audience": "urn:zitadel:iam:org:project:id:%s:aud" % project_id,
    }


def _write_machine_credentials(path: str, credentials: dict[str, str]) -> None:
    """Write the inter-service machine credentials JSON to *path*, owned by the service user.

    Backend services read this file (``IDENTITY_MACHINE_CREDENTIALS_FILE``) to
    perform the OAuth2 client_credentials exchange.  This applier runs as **root**
    in the Zitadel init container, but every backend service runs as the non-root
    ``appuser`` (uid ``_SERVICE_USER_UID``) with a read-only mount — so a file left
    ``root:root`` ``0600`` is unreadable by exactly the processes that must read it
    (``PermissionError``).  The file is therefore chowned to the service uid/gid;
    mode ``0600`` is kept, so ownership — not a broader world-readable mode — is
    what grants the read.  The secret is never logged.
    """
    directory = os.path.dirname(path)
    if directory and not os.path.exists(directory):
        os.makedirs(directory, exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(credentials, fh)
    try:
        os.chmod(path, 0o600)
    except OSError:
        # Best-effort hardening; the volume is not host-shared.
        pass
    # Hand the file to the non-root service user (uid/gid _SERVICE_USER_UID) that
    # consumes it.  This applier runs as root in the init container, so the chown
    # succeeds; if it does not, the credentials file stays unreadable by every
    # backend service, so fail loud rather than ship a deployment whose
    # inter-service auth is silently broken.
    try:
        os.chown(path, _SERVICE_USER_UID, _SERVICE_USER_UID)
    except OSError as exc:
        logger.error(
            "Failed to chown machine credentials '%s' to uid/gid %d: %s. "
            "Fix: the Zitadel init container must run as root so the credentials "
            "file it writes is readable by the non-root service user (uid %d) that "
            "performs the inter-service OAuth2 client_credentials exchange.",
            path,
            _SERVICE_USER_UID,
            exc,
            _SERVICE_USER_UID,
        )
        sys.exit(1)
    logger.info(
        "machine_credentials_written path=%s clientId=%s",
        path,
        credentials.get("clientId"),
    )


# ---------------------------------------------------------------------------
# Social IdP provisioning
# ---------------------------------------------------------------------------


def _list_idps(api: _Api) -> list[dict[str, Any]]:
    """Fetch all existing IdP configs at the instance level."""
    url = api.mgmt_base + "/idps/_search"
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list IdPs (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has iam-level permissions.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result  # type: ignore[return-value]
    return []


def _resolve_secret_ref(ref: str, idp_name: str) -> str:
    """Resolve a secret reference to its runtime value.

    Supports:
      - ``${VAR_NAME}``  -> reads ``os.environ["VAR_NAME"]``
      - ``/run/secrets/<name>`` -> reads file content

    Args:
        ref: The secret reference string from the artifact.
        idp_name: IdP name for error messages.

    Returns:
        The resolved secret value string.

    Raises:
        SystemExit(1): When the env var is absent, the file does not exist, or
            the ref format is not recognised.
    """
    if ref.startswith("${") and ref.endswith("}"):
        var_name = ref[2:-1]
        value = os.environ.get(var_name, "").strip()
        if not value:
            logger.error(
                "Social IdP '%s' references env var '%s' which is absent or empty. "
                "Fix: ensure the init-job container populates this env var from a "
                "secret ref before the applier runs.",
                idp_name,
                var_name,
            )
            sys.exit(1)
        return value
    if ref.startswith("/run/secrets/"):
        secret_path = ref
        if not os.path.exists(secret_path):
            logger.error(
                "Social IdP '%s' references docker secret file '%s' which does not exist. "
                "Fix: ensure the init-job mounts the secret at this path.",
                idp_name,
                secret_path,
            )
            sys.exit(1)
        with open(secret_path, "r", encoding="utf-8") as fh:
            return fh.read().strip()
    logger.error(
        "Social IdP '%s' has an unrecognised clientSecretRef format '%s'. "
        "Valid formats: '${VAR_NAME}' (env var) or '/run/secrets/<name>' "
        "(docker secret). Fix: regenerate the provisioning artifact with a "
        "valid secretRef provider ('env' or 'docker-secret').",
        idp_name,
        ref,
    )
    sys.exit(1)


def _create_social_idp(
    api: _Api,
    idp: dict[str, Any],
    client_secret: str,
) -> str:
    """Create a social IdP at the instance level and return its ``idpId``.

    Args:
        api: Connection context.
        idp: IdP dict from the artifact (``name``, ``type``, ``clientId``).
        client_secret: Resolved client secret value.

    Returns:
        The new IdP's ``idpId`` string.

    Raises:
        SystemExit(1): On unsupported type or API error.
    """
    idp_type = idp.get("type")
    idp_name = idp.get("name", "unknown")
    client_id = idp.get("clientId")

    if idp_type not in _SUPPORTED_IDP_TYPES:
        logger.error(
            "Social IdP '%s' has unsupported type '%s'. "
            "Supported types: %s. "
            "Fix: use a valid social provider type in the identity config.",
            idp_name,
            idp_type,
            sorted(_SUPPORTED_IDP_TYPES),
        )
        sys.exit(1)

    # Zitadel Management API uses lowercase type as the endpoint path segment
    # and a typed payload key.
    type_lower = str(idp_type).lower().replace("_", "")
    url = "%s/idps/%s" % (api.mgmt_base, type_lower)
    payload: dict[str, Any] = {
        "name": idp_name,
        "clientId": client_id,
        "clientSecret": client_secret,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create social IdP '%s' type=%s (HTTP %d): %s.",
            idp_name,
            idp_type,
            status,
            body,
        )
        sys.exit(1)
    idp_id = body.get("idpId") or body.get("id")
    if not isinstance(idp_id, str) or not idp_id:
        logger.error(
            "Create IdP '%s' response missing 'idpId'. Got: %s.",
            idp_name,
            body,
        )
        sys.exit(1)
    logger.info("social_idp_created name=%s type=%s idpId=%s", idp_name, idp_type, idp_id)
    return idp_id


def _update_social_idp(
    api: _Api,
    idp_id: str,
    idp: dict[str, Any],
    client_secret: str,
) -> None:
    """Update an existing social IdP at the instance level.

    Raises:
        SystemExit(1): On unsupported type or API error.
    """
    idp_type = idp.get("type")
    idp_name = idp.get("name", "unknown")
    client_id = idp.get("clientId")

    if idp_type not in _SUPPORTED_IDP_TYPES:
        logger.error(
            "Social IdP '%s' has unsupported type '%s'. "
            "Supported types: %s. "
            "Fix: use a valid social provider type.",
            idp_name,
            idp_type,
            sorted(_SUPPORTED_IDP_TYPES),
        )
        sys.exit(1)

    type_lower = str(idp_type).lower().replace("_", "")
    url = "%s/idps/%s/%s" % (api.mgmt_base, type_lower, idp_id)
    payload: dict[str, Any] = {
        "name": idp_name,
        "clientId": client_id,
        "clientSecret": client_secret,
    }
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update social IdP id=%s name=%s (HTTP %d): %s.",
            idp_id,
            idp_name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("social_idp_updated name=%s idpId=%s", idp_name, idp_id)


def _ensure_social_idps(
    api: _Api,
    identity_providers: list[dict[str, Any]],
) -> None:
    """Idempotently create or update social IdPs at the Zitadel instance level.

    Args:
        api: Connection context.
        identity_providers: List of IdP dicts from the artifact.
    """
    existing = _list_idps(api)
    existing_by_name: dict[str, dict[str, Any]] = {
        p.get("name", ""): p for p in existing
    }

    for idp in identity_providers:
        idp_name = idp.get("name")
        secret_ref = idp.get("clientSecretRef")

        if not isinstance(idp_name, str) or not idp_name:
            logger.error(
                "Identity provider entry missing 'name'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                idp,
            )
            sys.exit(1)
        if not isinstance(secret_ref, str) or not secret_ref:
            logger.error(
                "Identity provider '%s' missing 'clientSecretRef'. Got: %s. "
                "Fix: ensure socialProviders[].clientSecret is declared in the "
                "identity config with an 'env' or 'docker-secret' provider.",
                idp_name,
                idp,
            )
            sys.exit(1)

        client_secret = _resolve_secret_ref(secret_ref, idp_name)

        if idp_name in existing_by_name:
            existing_idp = existing_by_name[idp_name]
            idp_id = existing_idp.get("id")
            if not isinstance(idp_id, str) or not idp_id:
                logger.error(
                    "Existing IdP '%s' has no id. Got: %s.",
                    idp_name,
                    existing_idp,
                )
                sys.exit(1)
            _update_social_idp(api, idp_id, idp, client_secret)
        else:
            _create_social_idp(api, idp, client_secret)


# ---------------------------------------------------------------------------
# Token-claim-injection action (Complement Token flow)
# ---------------------------------------------------------------------------


def _token_claim_value_expr(source: str) -> str:
    """Return the JS value expression for a profile or metadata source kind.

    A ``metadata:<key>`` source reads the app-owned value the
    generated runtime (D2/D3, a separate task) wrote into the user's provider
    metadata, via the ``metadataMap`` lookup ``_build_token_claim_script``
    builds from ``ctx.v1.user.getMetadata().metadata`` -- independent of
    ``ctx.v1.getUser().human`` (metadata exists for every principal, not only
    human ones).  The value is read VERBATIM, with no decode: the Management-API
    write side base64-encodes the request body, but Zitadel v3 base64-*decodes*
    it once on write and stores the raw bytes, so ``getMetadata()`` inside the
    action already surfaces the original plain value.  Decoding it a second time
    here would corrupt it (proven on live Zitadel v3.0.0 staging: single-encode
    write + action decode yielded a garbage ``organizationId``); the round-trip
    is identity only when the action reads the metadata value as-is.

    Args:
        source: The ``tokenClaimAction.claims[].source`` kind from the artifact.

    Returns:
        The JavaScript expression that reads the value -- off the
        ``human``/``user`` profile object for a profile source, or the raw
        ``metadataMap`` lookup for a ``metadata:<key>`` source.

    Raises:
        SystemExit(1): When a non-metadata source kind is not recognised
            (artifact/applier version skew).
    """
    if source.startswith(_METADATA_CLAIM_SOURCE_PREFIX):
        key = source[len(_METADATA_CLAIM_SOURCE_PREFIX):]
        return "metadataMap[%s]" % json.dumps(key)
    expr = _TOKEN_CLAIM_SOURCE_EXPRESSIONS.get(source)
    if expr is None:
        logger.error(
            "tokenClaimAction claim has unknown source kind '%s'. Known kinds: %s "
            "(plus any 'metadata:<key>' source). "
            "Fix: regenerate the provisioning artifact with the matching "
            "datrix-codegen-docker version.",
            source,
            sorted(_TOKEN_CLAIM_SOURCE_EXPRESSIONS),
        )
        sys.exit(1)
    return expr


def _build_token_claim_script(action_name: str, claims: list[dict[str, Any]]) -> str:
    """Build the Complement-Token action JavaScript from the artifact claim list.

    Zitadel invokes the JS function whose identifier EQUALS the action name, so
    the emitted function is named *action_name* verbatim.  Profile-sourced
    claims read ``ctx.v1.getUser().human`` and are skipped entirely for a
    principal with no human profile (machine tokens).  Metadata-sourced claims
    read ``ctx.v1.user.getMetadata()`` -- a DIFFERENT, always-
    available API surface -- so they run regardless of whether the principal
    has a human profile.  Metadata values are stamped verbatim (Zitadel v3
    decodes the base64 request body on write and stores the raw value, so the
    action must not decode again -- see ``_token_claim_value_expr``).

    Args:
        action_name: The action name (also the JS function identifier).
        claims: List of ``{"claim": <claimPath>, "source": <kind>}`` dicts.

    Returns:
        The action script as a JavaScript source string.

    Raises:
        SystemExit(1): When a claim entry is missing ``claim``/``source``, or
            names an unrecognised non-metadata source kind.
    """
    validated: list[tuple[str, str]] = []
    for claim in claims:
        claim_name = claim.get("claim")
        source = claim.get("source")
        if not isinstance(claim_name, str) or not claim_name:
            logger.error(
                "tokenClaimAction claim entry is missing 'claim'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                claim,
            )
            sys.exit(1)
        if not isinstance(source, str) or not source:
            logger.error(
                "tokenClaimAction claim entry is missing 'source'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                claim,
            )
            sys.exit(1)
        validated.append((claim_name, source))

    profile_claims = [
        (n, s) for n, s in validated if not s.startswith(_METADATA_CLAIM_SOURCE_PREFIX)
    ]
    metadata_claims = [
        (n, s) for n, s in validated if s.startswith(_METADATA_CLAIM_SOURCE_PREFIX)
    ]

    lines: list[str] = ["function %s(ctx, api) {" % action_name]
    if profile_claims:
        lines += [
            "  var user = ctx.v1.getUser();",
            "  if (user && user.human) {",
            "    var human = user.human;",
            "    var value;",
        ]
        for claim_name, source in profile_claims:
            lines.append("    value = %s;" % _token_claim_value_expr(source))
            lines.append(
                "    if (value) { api.v1.claims.setClaim(%s, value); }"
                % json.dumps(claim_name)
            )
        lines.append("  }")
    if metadata_claims:
        lines += [
            "  var metadataMap = {};",
            "  ctx.v1.user.getMetadata().metadata.forEach(function (entry) {",
            "    metadataMap[entry.key] = entry.value;",
            "  });",
            "  var metaValue;",
        ]
        for claim_name, source in metadata_claims:
            lines.append("  metaValue = %s;" % _token_claim_value_expr(source))
            lines.append(
                "  if (metaValue) { api.v1.claims.setClaim(%s, metaValue); }"
                % json.dumps(claim_name)
            )
    lines.append("}")
    return "\n".join(lines)


def _list_actions(api: _Api) -> list[dict[str, Any]]:
    """Fetch all existing org-level actions (POST /actions/_search)."""
    url = api.mgmt_base + "/actions/_search"
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list actions (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has org-level permissions.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result  # type: ignore[return-value]
    return []


def _create_action(api: _Api, name: str, script: str) -> str:
    """Create the claim-injection action and return its id (POST /actions).

    ``allowedToFail`` is true so a transient action error degrades to Zitadel's
    prior behaviour (no claim stamped) instead of failing ALL token issuance.

    Raises:
        SystemExit(1): On API error or a response missing ``id``.
    """
    url = api.mgmt_base + "/actions"
    payload: dict[str, Any] = {
        "name": name,
        "script": script,
        "timeout": _TOKEN_CLAIM_ACTION_TIMEOUT,
        "allowedToFail": True,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create action '%s' (HTTP %d): %s.",
            name,
            status,
            body,
        )
        sys.exit(1)
    action_id = body.get("id")
    if not isinstance(action_id, str) or not action_id:
        logger.error(
            "Create action '%s' response missing 'id'. Got: %s.",
            name,
            body,
        )
        sys.exit(1)
    logger.info("action_created name=%s id=%s", name, action_id)
    return action_id


def _update_action(api: _Api, action_id: str, name: str, script: str) -> None:
    """Update the claim-injection action (PUT /actions/{id}).

    Re-asserts name/script/timeout/allowedToFail so a converged re-run keeps the
    action current.  Zitadel's "No changes" 400 on an unchanged re-apply is success.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/actions/%s" % (api.mgmt_base, action_id)
    payload: dict[str, Any] = {
        "name": name,
        "script": script,
        "timeout": _TOKEN_CLAIM_ACTION_TIMEOUT,
        "allowedToFail": True,
    }
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update action id=%s name=%s (HTTP %d): %s.",
            action_id,
            name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("action_updated id=%s name=%s", action_id, name)


def _set_trigger_actions(
    api: _Api,
    flow_type: str,
    trigger_type: str,
    action_ids: list[str],
) -> None:
    """Bind *action_ids* to a flow trigger (POST /flows/{flow}/trigger/{trigger}).

    This is a full-replace SET of the actions on the given trigger, so it is
    idempotent: re-applying the same ``action_ids`` converges to the same binding.
    Datrix owns provisioning, so no externally-managed action is clobbered.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/flows/%s/trigger/%s" % (api.mgmt_base, flow_type, trigger_type)
    payload: dict[str, Any] = {"actionIds": action_ids}
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to set trigger actions flow=%s trigger=%s (HTTP %d): %s.",
            flow_type,
            trigger_type,
            status,
            body,
        )
        sys.exit(1)
    logger.info(
        "trigger_actions_set flow=%s trigger=%s actions=%s",
        flow_type,
        trigger_type,
        action_ids,
    )


def _ensure_token_claim_action(api: _Api, action_spec: dict[str, Any]) -> None:
    """Idempotently converge the Complement-Token claim-injection action + bindings.

    Creates (or updates) the org-level action whose JS stamps the profile-sourced
    identity-field claims onto issued tokens, then binds it to the
    PreUserinfoCreation and PreAccessTokenCreation triggers of the Complement-Token
    flow.  Without this binding Zitadel's default access token carries no ``email``/
    ``name`` claim and the auth service rejects every human token with
    ``required_identity_field_missing``.

    Args:
        api: Connection context.
        action_spec: The artifact ``tokenClaimAction`` block
            (``{"name": str, "claims": list}``).

    Raises:
        SystemExit(1): When the spec is malformed or any API call fails.
    """
    name = action_spec.get("name")
    claims = action_spec.get("claims")
    if not isinstance(name, str) or not name:
        logger.error(
            "tokenClaimAction is missing 'name'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            action_spec,
        )
        sys.exit(1)
    if not isinstance(claims, list) or not claims:
        logger.error(
            "tokenClaimAction is missing a non-empty 'claims' list. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            action_spec,
        )
        sys.exit(1)

    script = _build_token_claim_script(name, claims)

    existing = _list_actions(api)
    action_id: str | None = None
    for action in existing:
        if action.get("name") == name:
            candidate = action.get("id")
            if isinstance(candidate, str) and candidate:
                action_id = candidate
            break

    if action_id is not None:
        logger.info("action_exists name=%s id=%s", name, action_id)
        _update_action(api, action_id, name, script)
    else:
        action_id = _create_action(api, name, script)

    for trigger_type in _TRIGGER_TYPES_TOKEN_CLAIM:
        _set_trigger_actions(
            api, _FLOW_TYPE_COMPLEMENT_TOKEN, trigger_type, [action_id]
        )


# ---------------------------------------------------------------------------
# Main orchestration
# ---------------------------------------------------------------------------


def _validate_project(project: dict[str, Any]) -> None:
    """Validate that a project entry has the required 'name' field.

    Args:
        project: Project dict from the artifact.

    Raises:
        SystemExit(1): When 'name' is absent or empty.
    """
    name = project.get("name")
    if not isinstance(name, str) or not name:
        logger.error(
            "Project entry in artifact is missing required 'name' field. "
            "Got: %s. Fix: regenerate the provisioning artifact.",
            project,
        )
        sys.exit(1)


def _patch_provider_plan_audiences(
    plan_path: str,
    project_ids: dict[str, str],
) -> None:
    """Rewrite Zitadel ``allowedAudiences`` sentinels to assigned project IDs.

    The generated provider plan emits each Datrix-provisioned Zitadel provider's
    ``allowedAudiences`` as a ``zitadel-project-audience:<projectName>`` sentinel,
    because the project ID is assigned by Zitadel only at provisioning time.  This
    replaces each sentinel with the matching project's assigned ID so the backend
    validators (which check the token ``aud`` against ``allowedAudiences``) accept
    the project ID Zitadel actually mints into access tokens.

    The plan file is rewritten **in place** (same inode) so the read-only mount
    the backend services share keeps pointing at the patched content.  Backend
    services depend on this init-job completing, so they never read a half-patched
    plan.

    Args:
        plan_path: Filesystem path to the writable ``identity-providers.json``.
        project_ids: Map of Zitadel project name -> assigned project ID, built
            while provisioning projects.

    Raises:
        SystemExit(1): When the plan is missing/invalid, or a sentinel references
            a project that was not provisioned (so its ID is unknown).
    """
    if not os.path.exists(plan_path):
        logger.error(
            "Provider plan not found at '%s'. "
            "Fix: verify the init-job mounts 'config/identity/identity-providers.json' "
            "read-write at this path (IDENTITY_PROVIDER_PLAN_FILE).",
            plan_path,
        )
        sys.exit(1)

    try:
        with open(plan_path, "r", encoding="utf-8") as fh:
            plan: dict[str, Any] = json.load(fh)
    except json.JSONDecodeError as exc:
        logger.error(
            "Provider plan at '%s' is not valid JSON: %s. "
            "Fix: regenerate the plan with datrix.",
            plan_path,
            exc,
        )
        sys.exit(1)

    providers = plan.get("providers")
    if not isinstance(providers, dict):
        logger.info("provider_plan_no_providers path=%s", plan_path)
        return

    patched = 0
    for provider_name, entry in providers.items():
        if not isinstance(entry, dict):
            continue
        audiences = entry.get("allowedAudiences")
        if not isinstance(audiences, list):
            continue
        new_audiences: list[Any] = []
        changed = False
        for aud in audiences:
            if isinstance(aud, str) and aud.startswith(_PROJECT_AUDIENCE_SENTINEL_PREFIX):
                project_name = aud[len(_PROJECT_AUDIENCE_SENTINEL_PREFIX):]
                project_id = project_ids.get(project_name)
                if not project_id:
                    logger.error(
                        "Provider '%s' allowedAudiences references project '%s' that "
                        "was not provisioned. Provisioned projects: %s. "
                        "Fix: ensure the provisioning artifact creates a project named "
                        "'%s' (the planner derives the sentinel and the artifact "
                        "project name from the same zitadelIdentity config).",
                        provider_name,
                        project_name,
                        sorted(project_ids),
                        project_name,
                    )
                    sys.exit(1)
                new_audiences.append(project_id)
                changed = True
            else:
                new_audiences.append(aud)
        if changed:
            entry["allowedAudiences"] = new_audiences
            patched += 1
            logger.info(
                "provider_plan_audience_patched provider=%s audiences=%s",
                provider_name,
                new_audiences,
            )

    if patched == 0:
        logger.info("provider_plan_no_audience_sentinels path=%s", plan_path)
        return

    with open(plan_path, "w", encoding="utf-8") as fh:
        json.dump(plan, fh, sort_keys=True)
    logger.info("provider_plan_audiences_written path=%s patched=%d", plan_path, patched)


def apply_provisioning(
    instance_url: str,
    host_header: str,
    token: str,
    provisioning_path: str,
) -> tuple[dict[str, str], dict[str, str] | None]:
    """Read the provisioning artifact and apply all resources via Zitadel Management API.

    Applies in order: Projects -> project Roles -> OIDC Apps -> machine user ->
    social IdPs, then the org-level Complement-Token claim-injection action (when
    the artifact declares one).  Every operation is idempotent via explicit
    get-before-create/update.  Partial failures exit non-zero immediately — no
    best-effort continuation.

    Args:
        instance_url: Internal Zitadel base URL (scheme+host+port).
        host_header: Instance external domain[:port] sent as the HTTP Host header.
        token: Bearer token (the FIRSTINSTANCE machine-user PAT).
        provisioning_path: Filesystem path to the provisioning artifact.

    Returns:
        ``(project_ids, machine_credentials)`` — ``project_ids`` maps Zitadel
        project name -> assigned project ID (used to rewrite the provider plan's
        ``allowedAudiences`` sentinels); ``machine_credentials`` is the inter-
        service machine credential material (``clientId``/``clientSecret``/
        ``audience``), or ``None`` when no project declares a ``machineUser``.
    """
    base = instance_url.rstrip("/")
    api = _Api(
        mgmt_base=base + _MANAGEMENT_BASE,
        token=token,
        host_header=host_header,
    )

    logger.info(
        "zitadel_applier_start instance=%s host=%s artifact=%s",
        base,
        host_header,
        provisioning_path,
    )

    artifact = _load_artifact(provisioning_path)

    projects: list[dict[str, Any]] = artifact["projects"]
    logger.info("provisioning_projects count=%d", len(projects))

    project_ids: dict[str, str] = {}
    machine_credentials: dict[str, str] | None = None
    for project in projects:
        _validate_project(project)
        project_name: str = project["name"]
        role_assertion = bool(project.get("projectRoleAssertion", False))

        project_id = _ensure_project(api, project_name, role_assertion)
        project_ids[project_name] = project_id

        roles: list[dict[str, Any]] = project.get("roles", [])
        if roles:
            logger.info(
                "applying_roles project=%s count=%d", project_name, len(roles)
            )
            _ensure_roles(api, project_id, roles)

        oidc_apps: list[dict[str, Any]] = project.get("oidcApps", [])
        if oidc_apps:
            logger.info(
                "applying_oidc_apps project=%s count=%d", project_name, len(oidc_apps)
            )
            _ensure_oidc_apps(api, project_id, oidc_apps)

        project_machine_credentials = _provision_machine_user(api, project, project_id)
        if project_machine_credentials is not None:
            if machine_credentials is not None:
                logger.error(
                    "More than one project declares a machineUser (second: '%s'). "
                    "Exactly one machine-audience identity provider is supported. "
                    "Fix: declare a single machine-audience identity provider.",
                    project_name,
                )
                sys.exit(1)
            machine_credentials = project_machine_credentials

        identity_providers: list[dict[str, Any]] = project.get("identityProviders", [])
        if identity_providers:
            logger.info(
                "applying_identity_providers project=%s count=%d",
                project_name,
                len(identity_providers),
            )
            _ensure_social_idps(api, identity_providers)

    # Converge the Complement-Token claim-injection action: Zitadel's default JWT
    # access token carries no profile claims (email/name), so without this action
    # every human token is rejected by the gateway's required-identity-field check.
    # Org-level and independent of projects, so it is applied once after all
    # projects.  Absent only when no provider declares a profile-sourceable field.
    token_claim_action = artifact.get("tokenClaimAction")
    if token_claim_action is not None:
        if not isinstance(token_claim_action, dict):
            logger.error(
                "Provisioning artifact 'tokenClaimAction' must be an object. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                token_claim_action,
            )
            sys.exit(1)
        logger.info("applying_token_claim_action name=%s", token_claim_action.get("name"))
        _ensure_token_claim_action(api, token_claim_action)
    else:
        logger.info("token_claim_action_skipped reason=no_profile_sourced_claims")

    logger.info("zitadel_applier_complete projects_applied=%d", len(projects))
    return project_ids, machine_credentials


def main() -> None:
    """Entry point: read env vars + PAT file and run apply_provisioning."""
    instance_url = _require_env("ZITADEL_INSTANCE_URL")
    host_header = _require_env("ZITADEL_HOST_HEADER")
    pat_file = _require_env("ZITADEL_PAT_FILE")
    provisioning_path = os.environ.get(
        "ZITADEL_PROVISIONING_PATH", _DEFAULT_PROVISIONING_PATH
    ).strip()
    if not provisioning_path:
        provisioning_path = _DEFAULT_PROVISIONING_PATH

    token = _read_pat(pat_file)

    project_ids, machine_credentials = apply_provisioning(
        instance_url=instance_url,
        host_header=host_header,
        token=token,
        provisioning_path=provisioning_path,
    )

    # Rewrite the provider plan's Zitadel allowedAudiences sentinels to the
    # project IDs Zitadel just assigned, so backend services validate the audience
    # the issued access tokens actually carry. Skipped only when the writable plan
    # path is not wired (e.g. external-only deployments with no provisioning).
    plan_file = os.environ.get("IDENTITY_PROVIDER_PLAN_FILE", "").strip()
    if plan_file:
        _patch_provider_plan_audiences(plan_file, project_ids)
    else:
        logger.info("provider_plan_writeback_skipped reason=no_plan_file_env")

    # Write the inter-service machine credentials (clientId/clientSecret/audience/
    # tokenUrl/hostHeader) onto the shared volume backend services read to acquire
    # their machine access tokens.  The token endpoint and Host header are
    # static for the deployment target and are recorded here alongside the
    # provisioning-time-minted client credentials so the service needs no env vars
    # to perform the OAuth2 client_credentials exchange.
    machine_credentials_file = os.environ.get(
        "IDENTITY_MACHINE_CREDENTIALS_FILE", ""
    ).strip()
    if machine_credentials is not None and machine_credentials_file:
        machine_credentials["tokenUrl"] = instance_url.rstrip("/") + "/oauth/v2/token"
        machine_credentials["hostHeader"] = host_header
        # The runtime metadata client (a separate task)
        # needs the instance base URL to reach /management/v1; recording it
        # here means no new env var is required on the backend service.
        machine_credentials["instanceOrigin"] = instance_url.rstrip("/")
        _write_machine_credentials(machine_credentials_file, machine_credentials)
    elif machine_credentials_file:
        logger.info("machine_credentials_skipped reason=no_machine_user_in_artifact")


if __name__ == "__main__":
    main()
